#!/usr/bin/env python3
"""Previous and current Rust nodes append/reopen one unchanged-format private datadir."""
import argparse,datetime,json,os,shutil,tempfile
from pathlib import Path
from lab import ROOT,save,sha
from verify_private_processes import Node,pack
DRIVER=sha(Path(__file__));HELPER=sha(ROOT/'scripts/verify_private_processes.py')
def main():
 parser=argparse.ArgumentParser();parser.add_argument('--baseline',type=Path,required=True);baseline=parser.parse_args().baseline.resolve();old_report=next(baseline/'results'/n for n in ['coincident-final-verification.json','activation-final-verification.json','lazy-aux-final-verification.json','lazy-world-final-verification.json']if(baseline/'results'/n).exists());old_proof=json.loads(old_report.read_text());assert old_proof['passed']and old_proof['source_build_sha256']==sha(baseline/'results/rust-build.json')
 build=json.loads((ROOT/'results/rust-build.json').read_text());pointer=json.loads((ROOT/'results/latest-private-processes.json').read_text());proof=json.loads((ROOT/pointer['directory']/'summary.json').read_text());assert proof['passed']and proof['lazy_etx']and proof['lazy_lockups']and proof['build_sha256']==sha(ROOT/'results/rust-build.json')
 binaries={};out=ROOT/'results'/('private-aux-compatibility-'+datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ'));out.mkdir();shutil.copy2(Path(__file__),out/'qualification-driver.py');shutil.copy2(ROOT/'scripts/verify_private_processes.py',out/'process-helper.py')
 for role,source in [('previous',baseline),('current',ROOT)]:
  bundle=json.loads((source/'results/private-node-bundle.json').read_text());binary=source/bundle['directory']/'quai-private-node';assert sha(binary)==bundle['files']['quai-private-node'];binaries[role]=out/(role+'-private-node');shutil.copy2(binary,binaries[role]);shutil.copy2(source/'results/rust-build.json',out/(role+'-rust-build.json'))
 corpus=json.loads((ROOT/'fixtures/protocol/canonical.json').read_text());rows=corpus['branches'][corpus['first_branch']]['vectors'];heads=corpus['canonical_events'][15]['canonical_hashes'];checks=[];nodes=[]
 def check(condition,label):assert condition,label;checks.append(label)
 def selected(status):return{k:status[k]for k in ['head','height','checkpoint','evm_root','etx_root','utxo_root','admitted_blocks']}
 with tempfile.TemporaryDirectory(prefix='quai-aux-compatible-')as temporary:
  temporary=Path(temporary);directory=temporary/'data';first=temporary/'first.json';second=temporary/'second.json';first.write_text(json.dumps(pack(rows[:3])));second.write_text(json.dumps(pack(rows[3:5])));shims=temporary/'deny';shims.mkdir();marker=temporary/'forbidden'
  for name in ['go','gofmt','protoc']:
   path=shims/name;path.write_text('#!/bin/sh\n: > '+str(marker)+'\nexit 97\n');path.chmod(0o755)
  env={**os.environ,'PATH':str(shims)+os.pathsep+os.environ['PATH'],'GO_QUAI_DIR':str(temporary/'missing-go')}
  try:
   previous=Node(binaries['previous'],directory,corpus['now'],env,out,'previous-initialize',nodes);previous.call('import',path=str(first));a=previous.status();check(a['height']==3 and a['head']==heads[3],'previous binary imports three frozen native blocks');identity=previous.ready['peer_id'];previous.stop();previous.cleanup();nodes.remove(previous)
   current=Node(binaries['current'],directory,corpus['now'],env,out,'current-reopen-append',nodes);b=current.status();check(selected(a)==selected(b),'current reader opens the previous selected checkpoint and roots without migration');check(b['lazy_etx']and b['lazy_lockups'],'current runtime uses lazy auxiliary state');check(current.ready['peer_id']==identity,'current binary preserves the existing peer identity');current.call('import',path=str(second));c=current.status();check(c['height']==5 and c['head']==heads[5],'current writer appends two frozen native blocks in the same datadir');check(c['evm_root']==rows[4]['evm_root']and c['etx_root']==rows[4]['etx_root'],'appended state retains the frozen Go commitments');current.stop();current.cleanup();nodes.remove(current)
   again=Node(binaries['previous'],directory,corpus['now'],env,out,'previous-read-current',nodes);d=again.status();check(selected(c)==selected(d),'previous reader reopens current-written checkpoint and all selected roots');check(again.ready['peer_id']==identity,'previous reader retains the same peer identity');again.stop();again.cleanup();nodes.remove(again);check(not marker.exists(),'no Go or protoc executable was attempted');save(out/'selected-generations.json',{'previous_written':selected(a),'current_read':selected(b),'current_written':selected(c),'previous_read':selected(d)})
  finally:
   for node in nodes:node.cleanup()
 assert sha(Path(__file__))==DRIVER and sha(ROOT/'scripts/verify_private_processes.py')==HELPER
 report={'passed':True,'build_sha256':sha(ROOT/'results/rust-build.json'),'previous_build_sha256':sha(baseline/'results/rust-build.json'),'reference_revision':build['reference_revision'],'assertions':len(checks),'checks':checks,'storage_format':'private-canonical-5 / keyed-state-3 / execution-codec-2 / hierarchy-delta-1','disk_format_changed':False,'previous_to_current_reopen':True,'current_to_previous_reopen':True,'blocks_imported':5,'new_native_block_coverage':False,'private_key_contents_in_artifacts':False,'go_commands_attempted':0,'public_network':False,'full_consensus':False,'canonical_public_sync':False,'driver_sha256':DRIVER,'process_helper_sha256':HELPER,'evidence_files':{p.name:sha(p)for p in out.iterdir()if p.is_file()},'scope':'Actual previous/current qualified Rust private-node executables share an unchanged-format ephemeral private datadir across clean restarts and five already-frozen early-profile native blocks. This qualifies selected generation and state-format compatibility at this scope; it does not establish large-state backward support, production upgrade safety, public sync or full consensus.'};save(out/'summary.json',report);save(ROOT/'results/latest-private-aux-compatibility.json',{'passed':True,'directory':str(out.relative_to(ROOT))});print(json.dumps({'passed':True,'assertions':len(checks),'directory':str(out.relative_to(ROOT))},indent=2))
if __name__=='__main__':main()
